tools.example:
I = imread('cameraman.tif');
h = fspecial('average', [9 9]);
B = imfilter(I, h, 'replicate');
montage({I, B})

I = im2double(imread('cameraman.tif'));
PSF = fspecial('motion', 21, 11);
blurred = imfilter(I, PSF, 'conv', 'circular');
restored = deconvwnr(blurred, PSF, 0.01);
montage({I, blurred, restored})

I = imread('cameraman.tif');
B1 = imgaussfilt(I, 2);
B2 = imgaussfilt(I, [1 6]);   % anisotropic
montage({I, B1, B2})

I = imread('eight.tif');
J = imnoise(I, 'salt & pepper', 0.1);
K = medfilt2(J, [3 3], 'symmetric');
montage({J, K})

I = imread('snowflakes.png');
domain = true(5,5);
maxfilt = ordfilt2(I, 25, domain);
minfilt = ordfilt2(I, 1, domain);
montage({minfilt, I, maxfilt})

I = im2double(imread('saturn.png'));
I = rgb2gray(I);
J = imnoise(I, 'gaussian', 0, 0.005);
[K, nvar] = wiener2(J, [5 5]);
montage({J, K})

I = imread('hestain.png');
B = imsharpen(I, 'Radius', 2, 'Amount', 1.5, 'Threshold', 0.02);
imshowpair(I, B, 'montage')

I = imread('coins.png');
patch = imcrop(I, [170 35 50 50]);
edgeVar = 2 * std(double(patch(:)))^2;
B = imbilatfilt(I, edgeVar, 5);
montage({I, B})

I = imread('cameraman.tif');
[gt, ni] = imdiffuseest(I, 'ConductionMethod', 'quadratic');
B = imdiffusefilt(I, 'GradientThreshold', gt, 'NumberOfIterations', ni, 'ConductionMethod', 'quadratic');
montage({I, B})

I = im2double(imread('cameraman.tif'));
J = imnoise(I, 'gaussian', 0, 0.005);
[K, dos] = imnlmfilt(J, 'SearchWindowSize', 15);
fprintf('Estimated DoS = %.4f\n', dos);
montage({J, K})

I = imread('circuit.tif');
BWs = edge(I, 'sobel');
[BWc, th] = edge(I, 'canny', [0.05 0.15], 2);
montage({BWs, BWc})
fprintf('Canny thresholds: %.3f %.3f\n', th);

I = imread('coins.png');
[Gmag, Gdir] = imgradient(I, 'prewitt');
imshow(Gmag, [])
L = watershed(imimposemin(Gmag, imerode(imbinarize(I), strel('disk',5))));

I = im2double(imread('cameraman.tif'));
[Gx, Gy] = imgradientxy(I, 'central');
mag = hypot(Gx, Gy);
imshow(mag, [])

SE = strel('disk', 7);
I = imread('rice.png');
bg = imopen(I, SE);
flat = I - bg;
montage({I, bg, flat})
disp(SE.Neighborhood)

bw = imbinarize(imread('circles.png'));
SE = strel('disk', 6);
eroded = imerode(bw, SE);
montage({bw, eroded})

bw = imread('text.png');
SE = strel('line', 11, 90);
thick = imdilate(bw, SE);
montage({bw, thick})

I = imread('rice.png');
background = imopen(I, strel('disk', 15));
I2 = I - background;
bw = imbinarize(imadjust(I2));
montage({I, background, I2, bw})

bw = imbinarize(imread('circbw.tif'));
closed = imclose(bw, strel('disk', 4));
montage({bw, closed})

I = imread('rice.png');
J = imtophat(I, strel('disk', 12));
bw = imbinarize(imadjust(J));
fprintf('Grains found: %d\n', max(bwlabel(bw), [], 'all'));

I = imread('pout.tif');
se = strel('disk', 10);
enhanced = I + imtophat(I, se) - imbothat(I, se);
montage({I, enhanced})

bw = imbinarize(imread('circbw.tif'));
skel = bwmorph(bw, 'skel', Inf);
spurless = bwmorph(skel, 'spur', 8);
bp = bwmorph(spurless, 'branchpoints');
montage({bw, skel, bp})

bw = imbinarize(imread('threads.png'));
skel = bwskel(bw, 'MinBranchLength', 15);
imshow(labeloverlay(uint8(bw)*255, skel, 'Transparency', 0))

I = imread('coins.png');
bw = imbinarize(I);
filled = imfill(bw, 'holes');
stats = regionprops(filled, 'Area');
fprintf('Mean coin area: %.0f px\n', mean([stats.Area]));

bw = imfill(imbinarize(imread('rice.png')), 'holes');
interior = imclearborder(bw, 4);
fprintf('%d of %d objects fully inside\n', ...
    max(bwlabel(interior),[],'all'), max(bwlabel(bw),[],'all'));

bw = imbinarize(imread('text.png'));
bw = bwareaopen(bw, 30);
imshow(bw)

bw = imfill(imbinarize(imread('coins.png')), 'holes');
biggest3 = bwareafilt(bw, 3);
midsize  = bwareafilt(bw, [1500 2500]);
montage({bw, biggest3, midsize})

bw = imbinarize(imread('circles.png'));
D = -bwdist(~bw);
D(~bw) = Inf;
L = watershed(imhmin(D, 2));
L(~bw) = 0;
imshow(label2rgb(L, 'jet', 'w'))

bw = imbinarize(imread('text.png'));
marker = false(size(bw));
marker(60, 50) = true;
selected = imreconstruct(marker & bw, bw);
montage({bw, selected})

I = imread('rice.png');
I2 = imtophat(I, strel('disk', 12));
markers = imextendedmax(I2, 20);
imshow(labeloverlay(I, markers))

I = imread('coins.png');
gmag = imgradient(I);
bw = imfill(imbinarize(I), 'holes');
fg = imerode(bw, strel('disk', 10));
bg = ~imdilate(bw, strel('disk', 5));
gmag2 = imimposemin(gmag, fg | bg);
L = watershed(gmag2);
imshow(label2rgb(L))

I = im2double(imread('cameraman.tif'));
PSF = fspecial('gaussian', 11, 3);
blur = imfilter(I, PSF, 'conv', 'circular');
noisy = imnoise(blur, 'gaussian', 0, 1e-5);
nsr = 1e-5 / var(I(:));
J = deconvwnr(noisy, PSF, nsr);
montage({noisy, J})

I = im2double(imread('cameraman.tif'));
truePSF = fspecial('gaussian', 9, 2.5);
blur = imfilter(I, truePSF, 'conv', 'circular');
initPSF = ones(9);
[J, psfr] = deconvblind(blur, initPSF, 30);
montage({blur, J})

A = imread('lowlight_11.jpg');
B = imlocalbrighten(A, 0.8, 'AlphaBlend', true);
montage({A, B})

A = imread('foggysf1.jpg');
[B, T] = imreducehaze(A, 0.9, 'Method', 'approxdcp');
montage({A, B})
figure, imshow(T)
